  "parameters": {
    "classroom_id": "a5695c1d-390d-4025-b013-2e218a2c1ca9",
    "objectives": [
      {
        "text": "identify and describe protons, neutrons and electrons in terms of their relative charges and relative masses"
      },
      {
        "text": "describe the distribution of mass and charge within an atom"
      },
      {
        "text": "deduce the numbers of protons, neutrons and electrons present in both atoms and ions given proton (atomic) and nucleon (mass) numbers and charge"
      },
      {
        "text": "describe the contribution of protons and neutrons to atomic nuclei in terms of proton (atomic) number and nucleon (mass) number"
      },
      {
        "text": "distinguish between isotopes on the basis of different numbers of neutrons present"
      },
      {
        "text": "recognise and use the symbolism for isotopes, where A is the nucleon (mass) number and Z is the proton (atomic) number"
      },
      {
        "text": "describe the number and relative energies of the s, p and d orbitals for the principal quantum numbers (shells) 1, 2 and 3 and also the 4s and 4p orbitals"
      },
      {
        "text": "describe and sketch the shapes of s and p orbitals"
      },
      {
        "text": "recall that each orbital can hold up to 2 electrons"
      },
      {
        "text": "recall the number of orbitals making up s-, p- and d- sub-shells, and the number of electrons that can fill s-,p- and d-sub-shells"
      },
      {
        "text": "describe the increase in energy between quantum numbers (shells) 1, 2 and 3 and between the s, p and d subshells in each shell"
      },
      {
        "text": "describe how electrons fill orbitals: - up to subshell 4d, including the filling of 4s before 3d (example in Fe, Fe2+, etc) - for orbitals with the same energy, electrons occupy each orbital singly before pairing"
      },
      {
        "text": "state the electronic configuration of atoms and ions given the proton (atomic) number and charge, using the convention 1s22s22p6, etc, and electrons in boxes representation, for example: oxygen"
      },
      {
        "text": "Describe and sketch how protons, neutrons and electrons behave in an electric field"
      }
    ],
    "school_id": 17,
