          "objectives": [
            {
              "id": 30749,
              "objective_key": "98b2c69a-5246-4a9d-b733-86d63db0f407",
              "objective_text": "By the end of this lesson the Chemistry Advanced Subsidiary level Learner should be able to: \ndefine and use the terms relative atomic, isotopic, molecular and formula masses,\nbased on the 12C scale",
              "order_index": 1
            },
            {
              "id": 30750,
              "objective_key": "2d6a325c-ec21-486b-8239-518bfcb507bd",
              "objective_text": "By the end of this lesson the Chemistry Advanced Subsidiary level Learner should be able to: define and use the term mole in terms of the Avogadro constant\n",
              "order_index": 2
            },
            {
              "id": 30751,
              "objective_key": "4ac0ee53-e976-4a89-986c-40c84d91757e",
              "objective_text": "By the end of this lesson the Chemistry Advanced Subsidiary level Learner should be able to: \nanalyse mass spectra in terms of isotopic abundances\n(knowledge of the working of the mass spectrometer is not required)",
              "order_index": 3
            },
            {
              "id": 30752,
              "objective_key": "a8f63bb1-4732-4116-af34-8062b992ae09",
              "objective_text": "By the end of this lesson the Chemistry Advanced Subsidiary level Learner should be able to: \ncalculate the relative atomic mass of an element given the relative abundances of\nits isotopes, or its mass spectrum",
              "order_index": 4
            },
            {
              "id": 30753,
              "objective_key": "c6ecaed6-3e0b-4b8e-8c87-dbbd89f66a29",
              "objective_text": "By the end of this lesson the Chemistry Advanced Subsidiary level Learner should be able to: calculate the percentage by mass of an element in a compound\n",
              "order_index": 5
            },
            {
              "id": 30754,
              "objective_key": "85fb0ff0-4c46-4917-acbc-46e3af503918",
              "objective_text": "By the end of this lesson the Chemistry Advanced Subsidiary level Learner should be able to: \ndefine and use the terms empirical and molecular formula",
              "order_index": 6
            },
            {
              "id": 30755,
              "objective_key": "3558afb1-9e0a-463a-8203-ee5a81fe2fa6",
              "objective_text": "By the end of this lesson the Chemistry Advanced Subsidiary level Learner should be able to: calculate empirical and molecular formulae, using combustion data or composition\nby mass\n",
              "order_index": 7
            }
          ]
        },
        {
          "id": 6508,
          "topicId": "c5a4e6d8-f24d-470b-bbb8-4b0362f4600e",
